for step in 0..5 {
	node_tree[comet_id].set_local_position(Vector2::create(step as f32 * 20.0, 0.0));
	node_tree.tick(&engine, 0.1);
}
assert_eq!(node_tree[comet_id].get_component::<TrailRenderer>().map(|trail| trail.get_point_count()), Some(5));

