struct TextureScene {
	scene_base: SceneBase,
	load_handle: Option<ImageDescriptionLoadHandle>,
}

impl Scene for TextureScene {
	fn get_scene_base(&self) -> &SceneBase {
		&self.scene_base
	}

	fn get_scene_base_mut(&mut self) -> &mut SceneBase {
		&mut self.scene_base
	}

