use vanilla::FrameProbe;

let mut frame_probe = FrameProbe::new();
frame_probe.set_seconds(0.5, 1.0);
let mut frame_count = 0;
while !frame_probe.measure_frame(1.0 / 60.0, 60.0) {
	frame_count += 1;
}
