use vanilla::{Color, DynamicFont, Graphic, Vector2};

fn draw_damage(dynamic_font: &DynamicFont, graphic: &mut Graphic, damage: i32) {
	graphic.set_image_tint_color(Some(Color::create(1.0, 0.85, 0.2, 1.0)));
