use std::cell::Cell;
use std::rc::Rc;
use vanilla::{Color, NodeTree, Paint, PopupMotion, PopupMotionState, Vector2};

let mut node_tree = NodeTree::new();
let root_id = node_tree.get_root_id();
let dim_id = node_tree.create_child(root_id, "Dim");
