node_tree.add_child(root_id, toolbar_id);
node_tree.add_child(toolbar_id, play_button_id);
PaneStyle::apply(&mut node_tree, toolbar_id, &[("justify-content", "flex-start"), ("padding", "0 8px")]);
node_tree.tick(&engine, 1.0 / 60.0);
node_tree.tick(&engine, 1.0 / 60.0);
